-- SCHEMATIC PLACEHOLDER — Phase 2 will sync with live risk engine on SQL Server
-- Module: loan_limit_rules
-- Last reviewed: 2026-04-10

CREATE OR ALTER PROCEDURE [risk].[usp_CalculateLoanLimit]
    @p_customer_id      BIGINT,
    @p_monthly_income   DECIMAL(18, 2),
    @p_employment_type  NVARCHAR(50),
    @p_tenure_months    INT,
    @p_credit_score     INT
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @v_base_limit     DECIMAL(18, 2) = 0;
    DECLARE @v_income_factor  DECIMAL(5, 2)  = 1.0;
    DECLARE @v_emp_adj        DECIMAL(5, 2)  = 1.0;
    DECLARE @v_ceiling        DECIMAL(18, 2) = 500000000;  -- 500 M IDR
    DECLARE @v_floor          DECIMAL(18, 2) = 1000000;    --   1 M IDR
    DECLARE @v_final_limit    DECIMAL(18, 2);

    -- Income bracket multiplier
    SELECT @v_income_factor =
        CASE
            WHEN @p_monthly_income >= 20000000 THEN 30.0
            WHEN @p_monthly_income >= 10000000 THEN 24.0
            WHEN @p_monthly_income >= 5000000  THEN 18.0
            WHEN @p_monthly_income >= 3000000  THEN 12.0
            ELSE                                    6.0
        END;

    SET @v_base_limit = @p_monthly_income * @v_income_factor;

    -- Employment-type adjustment from reference table
    SELECT @v_emp_adj = em.multiplier
    FROM   risk.ref_employment_multipliers AS em
    WHERE  em.employment_type = @p_employment_type
      AND  em.is_active = 1;

    SET @v_base_limit = @v_base_limit * ISNULL(@v_emp_adj, 0.80);

    -- Tenure haircut for new customers
    IF @p_tenure_months < 6
        SET @v_base_limit = @v_base_limit * 0.50;
    ELSE IF @p_tenure_months < 12
        SET @v_base_limit = @v_base_limit * 0.75;

    -- Hard gate on credit score
    IF @p_credit_score < 500
    BEGIN
        SELECT @v_floor AS loan_limit;
        RETURN;
    END;

    -- Apply ceiling / floor
    SET @v_final_limit =
        CASE
            WHEN @v_base_limit > @v_ceiling THEN @v_ceiling
            WHEN @v_base_limit < @v_floor   THEN @v_floor
            ELSE                                 @v_base_limit
        END;

    SELECT @v_final_limit AS loan_limit;
END;

-- SCHEMATIC PLACEHOLDER — Phase 2 will sync with live risk engine on SQL Server
-- Module: leverage_ratio_rules

CREATE OR ALTER FUNCTION [risk].[fn_GetMaxLeverageRatio]
(
    @p_segment        NVARCHAR(20),  -- 'retail' | 'sme' | 'corporate'
    @p_monthly_income DECIMAL(18, 2),
    @p_existing_debt  DECIMAL(18, 2)
)
RETURNS DECIMAL(5, 4)
AS
BEGIN
    DECLARE @v_base_ratio     DECIMAL(5, 4);
    DECLARE @v_income_adj     DECIMAL(5, 4) = 0.0;
    DECLARE @v_max_ratio      DECIMAL(5, 4) = 0.5500;
    DECLARE @v_result         DECIMAL(5, 4);

    -- Segment base ratios
    SELECT @v_base_ratio =
        CASE @p_segment
            WHEN 'corporate' THEN 0.4500
            WHEN 'sme'       THEN 0.3500
            WHEN 'retail'    THEN 0.3000
            ELSE                  0.2500
        END;

    -- High-income uplift for retail
    IF @p_segment = 'retail' AND @p_monthly_income >= 10000000
        SET @v_income_adj = 0.0500;

    -- Penalise existing heavy debt
    IF @p_existing_debt > @p_monthly_income * 12
        SET @v_income_adj = @v_income_adj - 0.0500;

    SET @v_result = @v_base_ratio + @v_income_adj;

    RETURN CASE
        WHEN @v_result > @v_max_ratio THEN @v_max_ratio
        WHEN @v_result < 0.1000       THEN 0.1000
        ELSE @v_result
    END;
END;

