CREATE OR ALTER PROCEDURE [risk].[usp_ComputeRepaymentScore]
    @p_customer_id      BIGINT,
    @p_lookback_months  INT = 24
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @v_on_time_pct     DECIMAL(5, 4);
    DECLARE @v_missed_count    INT;
    DECLARE @v_early_settle    INT;
    DECLARE @v_raw_score       DECIMAL(10, 4);
    DECLARE @v_final_score     INT;

    -- Aggregate payment history over lookback window
    SELECT
        @v_on_time_pct  = AVG(CASE WHEN ph.days_late = 0 THEN 1.0 ELSE 0.0 END),
        @v_missed_count = SUM(CASE WHEN ph.days_late > 30  THEN 1 ELSE 0 END),
        @v_early_settle = SUM(CASE WHEN ph.settled_early = 1 THEN 1 ELSE 0 END)
    FROM risk.payment_history AS ph
    WHERE ph.customer_id = @p_customer_id
      AND ph.due_date >= DATEADD(MONTH, -@p_lookback_months, GETDATE());

    -- Weighted composite score (weights placeholder)
    SET @v_raw_score =
          (@v_on_time_pct  * 600.0)
        + (@v_early_settle * 20.0)
        - (@v_missed_count * 50.0);

    -- Clamp to [0, 1000]
    SET @v_final_score = CASE
        WHEN @v_raw_score > 1000 THEN 1000
        WHEN @v_raw_score < 0    THEN 0
        ELSE CAST(@v_raw_score AS INT)
    END;

    SELECT @v_final_score AS repayment_score;
END;

