CREATE OR ALTER FUNCTION [risk].[fn_IsKycEligible]
(
    @p_customer_id   BIGINT,
    @p_product_code  NVARCHAR(20)
)
RETURNS BIT
AS
BEGIN
    DECLARE @v_kyc_status       NVARCHAR(20);
    DECLARE @v_id_verified      BIT;
    DECLARE @v_pep_flag         BIT;
    DECLARE @v_sanction_flag    BIT;
    DECLARE @v_age              INT;
    DECLARE @v_result           BIT = 0;

    SELECT
        @v_kyc_status    = c.kyc_status,
        @v_id_verified   = c.id_verified,
        @v_pep_flag      = c.is_pep,
        @v_sanction_flag = c.is_sanctioned,
        @v_age           = DATEDIFF(YEAR, c.date_of_birth, GETDATE())
    FROM risk.customers AS c
    WHERE c.customer_id = @p_customer_id;

    -- Hard blocks
    IF @v_sanction_flag = 1 RETURN 0;
    IF @v_pep_flag = 1      RETURN 0;
    IF @v_id_verified = 0   RETURN 0;
    IF @v_age < 18          RETURN 0;
    IF @v_age > 70 AND @p_product_code = 'LONG_TERM_LOAN' RETURN 0;

    -- KYC status gate
    IF @v_kyc_status NOT IN ('verified', 'enhanced_verified') RETURN 0;

    RETURN 1;
END;

-- SCHEMATIC PLACEHOLDER — Phase 2 will sync with live risk engine on SQL Server
-- Module: interest_rate_adjustment

CREATE OR ALTER FUNCTION [risk].[fn_ComputeAdjustedRate]
(
    @p_customer_id   BIGINT,
    @p_base_rate     DECIMAL(6, 4),
    @p_risk_tier     NVARCHAR(10),   -- 'AAA' | 'AA' | 'A' | 'BBB' | 'BB' | 'B'
    @p_product_code  NVARCHAR(20)
)
RETURNS DECIMAL(6, 4)
AS
BEGIN
    DECLARE @v_tier_spread      DECIMAL(6, 4);
    DECLARE @v_promo_discount   DECIMAL(6, 4) = 0.0;
    DECLARE @v_loyalty_discount DECIMAL(6, 4) = 0.0;
    DECLARE @v_tenure_months    INT;
    DECLARE @v_final_rate       DECIMAL(6, 4);

    -- Risk-tier spread lookup
    SELECT @v_tier_spread = rt.spread
    FROM   risk.ref_risk_tier_spreads AS rt
    WHERE  rt.tier_code = @p_risk_tier
      AND  rt.is_active = 1;

    -- Active promotional discount
    SELECT TOP 1 @v_promo_discount = p.discount_rate
    FROM   risk.promotions AS p
    WHERE  p.product_code = @p_product_code
      AND  GETDATE() BETWEEN p.valid_from AND p.valid_to
      AND  p.is_active = 1
    ORDER BY p.discount_rate DESC;

    -- Loyalty discount for long-tenure customers
    SELECT @v_tenure_months = DATEDIFF(MONTH, c.onboard_date, GETDATE())
    FROM   risk.customers AS c
    WHERE  c.customer_id = @p_customer_id;

    IF @v_tenure_months >= 36  SET @v_loyalty_discount = 0.0025;
    IF @v_tenure_months >= 60  SET @v_loyalty_discount = 0.0050;

    SET @v_final_rate =
          @p_base_rate
        + ISNULL(@v_tier_spread, 0.02)
        - ISNULL(@v_promo_discount, 0.0)
        - @v_loyalty_discount;

    -- Floor at regulatory minimum
    RETURN CASE WHEN @v_final_rate < 0.0600 THEN 0.0600 ELSE @v_final_rate END;
END;

