CREATE OR ALTER PROCEDURE [risk].[usp_EnforceCreditUtilizationCap]
    @p_customer_id   BIGINT,
    @p_new_drawdown  DECIMAL(18, 2)
AS
BEGIN
    SET NOCOUNT ON;

    DECLARE @v_total_limit      DECIMAL(18, 2);
    DECLARE @v_total_used       DECIMAL(18, 2);
    DECLARE @v_current_util     DECIMAL(5, 4);
    DECLARE @v_cap              DECIMAL(5, 4) = 0.8500;  -- 85% utilization cap
    DECLARE @v_post_drawdown    DECIMAL(5, 4);
    DECLARE @v_is_allowed       BIT = 1;

    -- Aggregate all active facilities
    SELECT
        @v_total_limit = SUM(cf.credit_limit),
        @v_total_used  = SUM(cf.outstanding_balance)
    FROM risk.credit_facilities AS cf
    WHERE cf.customer_id = @p_customer_id
      AND cf.status = 'active';

    IF @v_total_limit IS NULL OR @v_total_limit = 0
    BEGIN
        SELECT 0 AS is_allowed, NULL AS current_utilization, NULL AS projected_utilization;
        RETURN;
    END;

    SET @v_current_util  = @v_total_used / @v_total_limit;
    SET @v_post_drawdown = (@v_total_used + @p_new_drawdown) / @v_total_limit;

    IF @v_post_drawdown > @v_cap
        SET @v_is_allowed = 0;

    SELECT
        @v_is_allowed    AS is_allowed,
        @v_current_util  AS current_utilization,
        @v_post_drawdown AS projected_utilization;
END;

